        meta_title="Wedding Motifs: Meaningful Patterns & Lighting Ideas",
        description="Explore classic wedding motifs and patterns, what they symbolize, and how to light them with fairy lights, string lights and candles for a glowing reception.",
        keyword="wedding motifs",
        category="Events & Holidays",
        image="wedding-reception-lights",
        image_alt="Outdoor wedding reception at night under strings of warm lights",
